function primaryNav() {
    const page=location.pathname.split('/').pop()?.slice(0,7),groups=[
      {key:'home',pages:['m03-p01','m03-p02'],label:'首页',href:'m03-p02.html',path:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-8h6v8'},
